+ static constexpr size_t RADIX = 256;
+ static constexpr uint32_t RADIX_MASK = RADIX - 1;
+
+ extern "C" void sort_u32(uint32_t* a, size_t n) {
+     if (n <= 1) return;
+     // Early exit for already sorted or reverse sorted arrays.
+     bool asc = true, desc = true;
+     uint32_t maxv = a[0];
+     for (size_t i = 1; i < n; ++i) {
+         uint32_t v = a[i];
+         if (a[i-1] > v) asc = false;
+         if (a[i-1] < v) desc = false;
+         if (v > maxv) maxv = v;
+     }
+     if (asc) return;
+     if (desc) {
+         std::reverse(a, a + n);
+         return;
+     }
+     // Determine number of passes needed based on max value.
+     size_t passes = 1;
+     if (maxv >> 8)  passes = 2;
+     if (maxv >> 16) passes = 3;
+     if (maxv >> 24) passes = 4;
+     // Reuse a static scratch buffer to avoid allocation overhead.
+     static std::vector<uint32_t> tmp_buffer;
+     if (tmp_buffer.size() < n) tmp_buffer.resize(n);
+     uint32_t* src = a;
+     uint32_t* dst = tmp_buffer.data();
+     // 8‑bit histogram and distribution.
+     uint32_t hist[RADIX];
+     uint32_t pos[RADIX];
+     for (size_t pass = 0; pass < passes; ++pass) {
+         unsigned shift = pass * 8;
+         std::memset(hist, 0, sizeof(hist));
+         for (size_t i = 0; i < n; ++i) {
+             ++hist[(src[i] >> shift) & RADIX_MASK];
+         }
+         uint32_t sum = 0;
+         for (size_t b = 0; b < RADIX; ++b) {
+             pos[b] = sum;
+             sum += hist[b];
+         }
+         for (size_t i = 0; i < n; ++i) {
+             uint32_t v = src[i];
+             uint32_t key = (v >> shift) & RADIX_MASK;
+             dst[pos[key]++] = v;
+         }
+         std::swap(src, dst);
+     }
+     if (src != a) std::memcpy(a, src, n * sizeof(uint32_t));
+ }
